package main
func counter(n int) func() int { return func() int {n++;return n} }
func copies() int { f:=counter(2); g:=f; a:=g(); b:=f();return 10*a+b }
func separate() int {f:=counter(2); g:=counter(7); a:=f(); b:=g();return 10*a+b }
func late() int {n:=2; f:=func()int{return n}; n=7;return f()}
func named() int { f:=func(a int)(r int){ a++; r=a; return }; x:=3;return 10*f(x)+x }
func fresh() int {f:=func()[]int{return []int{3,7}};a:=f();b:=f();b[0]=9;return 10*a[0]+b[0]}
func unordered() int { n:=2; f:=func() int {n=7;return 3};return f()+n}
func clearGeneric[T ~[]int|~map[int]int](x T) {clear(x)}
func resetSlice() int {s:=[]int{2,8};a:=s;clearGeneric(s);return len(a)*100+a[0]*10+a[1]}
func resetMap() int {m:=map[int]int{1:2,3:4};a:=m;clearGeneric(m);return len(a)*10+a[1]}
func dirty(s []int) int {s[0]=9;return 1}
func sequencedSlice() int {s:=[]int{4}; k:=dirty(s);return 10*k+s[0]}
func unorderedSlice() int {s:=[]int{4};return dirty(s)+s[0]}
